ts.file<pre><code>import { Component } from '@angular/core';

@Component({
  selector: 'app-parent',
  templateUrl: './parent.component.html',
  styleUrls: ['./parent.component.css']
})
export class ParentComponent {
  cities = [
    { cityId: 101, cityName: 'Hyderabad' },
    { cityId: 102, cityName: 'VijayaWada' },
    { cityId: 103, cityName: 'Maharashtra' },
    { cityId: 104, cityName: 'Bengaluru' }
  ];

  skills: string[] = ['Angular', 'React', 'Vue', 'Node.js', 'Python'];

  formModel: any = {
    firstName: '',
    lastName: '',
    gender: '',
    dob: '',
    city: '',
    email: '',
    age: null,
    password: '',
    address: '',
    appointmentTime: '',
    cricket: false,
    football: false,
    carrom: false,
    skills: [],
    resume: null
  };

  fileName = '';

  onSubmit(form: any): void {
    if (form.valid) {
      console.log('Form Submitted:', this.formModel);
    } else {
      console.warn('Form Invalid');
    }
  }

  onFileChange(event: any): void {
    const file = event.target.files[0];
    if (file) {
      this.formModel.resume = file;
      this.fileName = file.name;
    }
  }

  onSelectAllSkills(event: any): void {
    if (event.target.checked) {
      this.formModel.skills = [...this.skills];
    } else {
      this.formModel.skills = [];
    }
  }
}
</code></pre> html<pre><code>&lt;div class="container-fluide mx-3 card p-3"&gt;
  &lt;form #formRef="ngForm" (ngSubmit)="onSubmit(formRef)"&gt;
    &lt;div class="row"&gt;

      &lt;!-- First Name --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;First Name&lt;/mat-label&gt;
          &lt;input matInput name="firstName" [(ngModel)]="formModel.firstName" required #firstName="ngModel"&gt;
          &lt;mat-error *ngIf="firstName.invalid &amp;&amp; firstName.touched"&gt;First Name is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Last Name --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Last Name&lt;/mat-label&gt;
          &lt;input matInput name="lastName" [(ngModel)]="formModel.lastName" required #lastName="ngModel"&gt;
          &lt;mat-error *ngIf="lastName.invalid &amp;&amp; lastName.touched"&gt;Last Name is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Gender --&gt;
      &lt;div class="col-3"&gt;
        &lt;label&gt;Gender:&lt;/label&gt;&lt;br&gt;
        &lt;mat-radio-group name="gender" [(ngModel)]="formModel.gender" required #gender="ngModel"&gt;
          &lt;mat-radio-button value="male"&gt;Male&lt;/mat-radio-button&gt;
          &lt;mat-radio-button value="female"&gt;Female&lt;/mat-radio-button&gt;
        &lt;/mat-radio-group&gt;
        &lt;mat-error *ngIf="gender.invalid &amp;&amp; gender.touched"&gt;Gender is required&lt;/mat-error&gt;
      &lt;/div&gt;

      &lt;!-- Date of Birth --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Date of Birth&lt;/mat-label&gt;
          &lt;input matInput [matDatepicker]="picker" name="dob" [(ngModel)]="formModel.dob" 
                                                required #dob="ngModel"&gt;
          &lt;mat-datepicker-toggle matIconSuffix [for]="picker"&gt;&lt;/mat-datepicker-toggle&gt;
          &lt;mat-datepicker #picker&gt;&lt;/mat-datepicker&gt;
          &lt;mat-error *ngIf="dob.invalid &amp;&amp; dob.touched"&gt;DOB is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- City Dropdown --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Select City&lt;/mat-label&gt;
          &lt;mat-select name="city" [(ngModel)]="formModel.city" required #city="ngModel"&gt;
            &lt;mat-option *ngFor="let c of cities" [value]="c.cityId"&gt;{{ c.cityName }}&lt;/mat-option&gt;
          &lt;/mat-select&gt;
          &lt;mat-error *ngIf="city.invalid &amp;&amp; city.touched"&gt;City is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Email --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Email&lt;/mat-label&gt;
          &lt;input matInput name="email" [(ngModel)]="formModel.email" required email #email="ngModel"&gt;
          &lt;mat-error *ngIf="email.errors?.['required'] &amp;&amp; email.touched"&gt;Email is required&lt;/mat-error&gt;
          &lt;mat-error *ngIf="email.errors?.['email'] &amp;&amp; email.touched"&gt;Invalid email&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Age --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Age&lt;/mat-label&gt;
          &lt;input matInput type="number" name="age" [(ngModel)]="formModel.age" required #age="ngModel"&gt;
          &lt;mat-error *ngIf="age.invalid &amp;&amp; age.touched"&gt;Age is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Password --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Password&lt;/mat-label&gt;
          &lt;input matInput type="password" name="password" [(ngModel)]="formModel.password" required 
                                                        #password="ngModel"&gt;
          &lt;mat-error *ngIf="password.invalid &amp;&amp; password.touched"&gt;Password is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Address (Textarea) --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Address&lt;/mat-label&gt;
          &lt;textarea matInput name="address" [(ngModel)]="formModel.address" required #address="ngModel"&gt;&lt;/textarea&gt;
          &lt;mat-error *ngIf="address.invalid &amp;&amp; address.touched"&gt;Address is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Time Input --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Appointment Time&lt;/mat-label&gt;
          &lt;input matInput type="time" name="appointmentTime" [(ngModel)]="formModel.appointmentTime" 
                                                required #appointmentTime="ngModel"&gt;
          &lt;mat-error *ngIf="appointmentTime.invalid &amp;&amp; appointmentTime.touched"&gt;Time is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

      &lt;!-- Hobbies (Checkboxes) --&gt;
      &lt;div class="col-3"&gt;
        &lt;label&gt;Hobbies:&lt;/label&gt;&lt;br&gt;
        &lt;mat-checkbox [(ngModel)]="formModel.cricket" name="cricket"&gt;Cricket&lt;/mat-checkbox&gt;
        &lt;mat-checkbox [(ngModel)]="formModel.football" name="football"&gt;Football&lt;/mat-checkbox&gt;
        &lt;mat-checkbox [(ngModel)]="formModel.carrom" name="carrom"&gt;Carrom&lt;/mat-checkbox&gt;
      &lt;/div&gt;

      &lt;!-- Resume Upload --&gt;
      &lt;div class="col-3"&gt;
        &lt;label&gt;Upload Resume&lt;/label&gt;&lt;br&gt;
        &lt;input type="file" (change)="onFileChange($event)"&gt;
        &lt;div *ngIf="fileName"&gt;Selected: {{ fileName }}&lt;/div&gt;
      &lt;/div&gt;

      &lt;!-- Multi-Select Skills --&gt;
      &lt;div class="col-3"&gt;
        &lt;mat-form-field appearance="outline"&gt;
          &lt;mat-label&gt;Select Skills&lt;/mat-label&gt;
          &lt;mat-select name="skills" [(ngModel)]="formModel.skills" multiple required #skills="ngModel"&gt;
            &lt;mat-option&gt;
              &lt;mat-checkbox (change)="onSelectAllSkills($event)"&gt;All&lt;/mat-checkbox&gt;
            &lt;/mat-option&gt;
            &lt;mat-option *ngFor="let skill of skills" [value]="skill"&gt;{{ skill }}&lt;/mat-option&gt;
          &lt;/mat-select&gt;
          &lt;mat-error *ngIf="skills.invalid &amp;&amp; skills.touched"&gt;At least one skill is required&lt;/mat-error&gt;
        &lt;/mat-form-field&gt;
      &lt;/div&gt;

    &lt;/div&gt;

    &lt;div class="mt-3"&gt;
      &lt;button class="btn btn-success" type="submit" [disabled]="formRef.invalid"&gt;Submit&lt;/button&gt;
    &lt;/div&gt;
  &lt;/form&gt;
&lt;/div&gt;
</code></pre>

parent.ts<pre><code>import { CommonModule } from '@angular/common';
import { Component, OnInit ,ChangeDetectionStrategy} from '@angular/core';
import { FormControl, Validators } from '@angular/forms';
import { FormGroup, ReactiveFormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import {MatDatepickerModule} from '@angular/material/datepicker';
import {provideNativeDateAdapter} from '@angular/material/core';
import { Child } from '../child/child';
import { MatTimepickerModule } from '@angular/material/timepicker';

export interface DataFromParent {
  firstNameFc: string;
  lastNameFc: string;
  genderFc: string;
  dobFc: Date;
  cityFc: number;
  emailFc: string;
  ageFc: number;
  passwordFc: string;
  addressFc: string;
  appointmentTimeFc: string;
  cricketFc: boolean;
  footballFc: boolean;
  carromFc: boolean;
  skillsFc: string[];
  resumeFileName?: string;
}

@Component({
  selector: 'app-parent',
  imports: [Child,MatDatepickerModule,CommonModule,MatTimepickerModule,MatFormFieldModule,MatInputModule,MatRadioModule,MatCheckboxModule,ReactiveFormsModule,MatSelectModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [provideNativeDateAdapter()],
  templateUrl: './parent.html',
  styleUrl: './parent.css'
})
export class Parent implements OnInit{

  myForm:FormGroup
  city:any[]=[]
  skills: string[] = ['Angular', 'React', 'Vue', 'Node.js', 'Python'];

  ngOnInit(): void {
    this.getCities();
    this.myForm=new FormGroup({
     firstNameFc:new FormControl('',Validators.required),
     lastNameFc:new FormControl(''),
     genderFc:new FormControl(''),
     cityFc:new FormControl(''),
     carromFc:new FormControl(''),
     footballFc:new FormControl(''),
     cricketFc:new FormControl(''),
     dobFc:new FormControl(''),
     addressFc: new FormControl(''),                  // Textarea
     appointmentTimeFc: new FormControl(''),          // Time picker
     emailFc: new FormControl('', Validators.email),  // Email
     ageFc: new FormControl(null),                    // Number
     passwordFc: new FormControl(''),                 // Password
     resumeFc: new FormControl(null), 
     skillsFc: new FormControl([], Validators.required),
    })
  }
  getCities():void{
    this.city=[
      {cityId:101,cityName:'Hyderabad'},
      {cityId:102,cityName:'VijayaWada'},
      {cityId:103,cityName:'Maharastra'},
      {cityId:104,cityName:'Bengaloor'}
    ]
  }
  sendDataToChild:any;
  data:DataFromParent[]=[]
  submitForm(){
    if (this.myForm.valid) {
      const formValue = this.myForm.value as DataFromParent;
      this.data.push(formValue);
      console.log(this.data, 'array');
    }
  }
  receiveDataFromChild(data: DataFromParent[]): void {
    const item = data[0];
    this.myForm.patchValue({
      firstNameFc: item.firstNameFc,
      lastNameFc: item.lastNameFc,
      genderFc: item.genderFc,
      dobFc: item.dobFc,
      cityFc: item.cityFc,
      emailFc: item.emailFc,
      ageFc: item.ageFc,
      passwordFc: item.passwordFc,
      addressFc: item.addressFc,
      appointmentTimeFc: item.appointmentTimeFc,
      cricketFc: item.cricketFc,
      footballFc: item.footballFc,
      carromFc: item.carromFc,
      skillsFc: item.skillsFc,
    });
  }

  resetForm(): void {
    this.myForm.reset();
    this.data = [];
  }  

  onFileSelected(event: any) {
    const file = event.target.files[0];
    if (file) {
      this.myForm.patchValue({
        resumeFc: file,
      });
      // Store just the filename
      const latest = this.data[this.data.length - 1];
      if (latest) {
        latest.resumeFileName = file.name;
      }
    }
  }

onSelectall(event: any) {
    if (event.checked) {
      this.myForm.patchValue({ skillsFc: this.skills });
    } else {
      this.myForm.patchValue({ skillsFc: [] });
    }
  }
}
</code></pre> parent.html<pre><code>note:    &lt;!--firstName,email and Select skills here validation anedi only e fields ke icham--&gt;
&lt;div class="container-fluide mx-3"&gt;
    &lt;form [formGroup]="myForm"&gt;
        &lt;!-- firstName --&gt;
        &lt;mat-form-field appearance="outline" class="mx-2"&gt;
            &lt;mat-label&gt;FirstName&lt;/mat-label&gt;
            &lt;input type="text" matInput placeholder="firstName*" formControlName="firstNameFc"&gt;
            &lt;mat-error
                *ngIf="myForm.get('firstNameFc')?.hasError('required') &amp;&amp; 
