        &lt;!-- lastName --&gt;
        &lt;mat-form-field appearance="outline"&gt;
            &lt;mat-label&gt;LastName&lt;/mat-label&gt;
            &lt;input type="text" matInput placeholder="lastName" formControlName="lastNameFc"&gt;
        &lt;/mat-form-field&gt;&lt;br&gt;
        &lt;!-- gender --&gt;
        &lt;mat-radio-group aria-label="Select an option" formControlName="genderFc"&gt;
            &lt;mat-radio-button value="male"&gt;Male&lt;/mat-radio-button&gt;
            &lt;mat-radio-button value="female"&gt;Female&lt;/mat-radio-button&gt;
        &lt;/mat-radio-group&gt;
        &lt;!-- checkbox --&gt;
        &lt;section class="example-section"&gt;
            &lt;mat-checkbox class="example-margin" formControlName="cricketFc"&gt;Cricket&lt;/mat-checkbox&gt;
            &lt;mat-checkbox class="example-margin" formControlName="footballFc"&gt;FootBall&lt;/mat-checkbox&gt;
            &lt;mat-checkbox class="example-margin" formControlName="carromFc"&gt;Carrom&lt;/mat-checkbox&gt;
        &lt;/section&gt;
        &lt;!-- dob --&gt;
