@Pipe({
  name: 'filter',
  standalone: true
})
export class FilterPipe implements PipeTransform {
      transform(value: any, input: string,searchableList : any) {
    // console.log(value)
    // console.log(searchableList)
      if (input &amp;&amp; value) {
   //     console.log(input)
      input = typeof(input)==='string'?input.toLowerCase():input;
      return value.filter(function (el: any) {
      var isTrue = false;
      for(var k in searchableList ){
        if(el[searchableList[k]]){
        if(el[searchableList[k]].toString().toLowerCase().indexOf(input) &gt; -1){
         isTrue = true;
        }
        if(isTrue){
         return el
        }
       }
       }
     })
    }
    return value;

  }
} 
